class CtlHorizontal{constructor(){this.CtlHrLoop()}CtlHrLoop(){this.parentWrp=jQuery(".ctl-horizontal-wrapper"),this.parentWrp.map((t,i)=>{const e=jQuery(i).find(".ctl-slider-container")[0];this.initializeMainSlider(e)})}initializeMainSlider=t=>{if(!t)return;const i=this.ctlSlideAttribute(t);new Swiper(t,i)};ctlSlideAttribute=t=>{const i=t.closest(".ctl-horizontal-wrapper"),e=jQuery(i),r=e.find(".ctl-button-next")[0],n=e.find(".ctl-button-prev")[0],l={slidesPerGroup:1,slidesPerView:1,breakpoints:{640:{slidesPerView:1},768:{slidesPerView:2},1024:{slidesPerView:""===e.data("items")?6:parseInt(e.data("items"))}}};return r&&n&&(l.navigation={nextEl:r,prevEl:n,addIcons:!1}),l}}new CtlHorizontal;